{{ (function(){
 var rivit = appsmith.store.tiskiRivit || [];
 var CSS = "html,body{margin:0;height:100%;background:#FFFFFF;font-family:Inter,system-ui,sans-serif;overflow-y:auto}table{width:100%;border-collapse:collapse;font-size:14px}td{padding:9px 8px;border-bottom:1px solid #EEF0F2;vertical-align:top}td.n{width:28px;color:#9CA3AF}td.x{width:34px;text-align:center}.nimi{font-weight:700;color:#1F2937}.alle{color:#6B7280;font-size:12px;margin-top:2px}.poista{display:inline-block;width:26px;height:26px;line-height:24px;border-radius:50%;background:#F3F4F6;color:#4B5563;cursor:pointer;font-size:16px}.poista:hover{background:#FEE2E2;color:#991B1B}.tyhja{padding:26px 16px;color:#6B7280;font-size:14px;text-align:center}";
 var JS = "document.addEventListener(\"click\",function(e){var x=e.target.closest(\".poista\");if(x){parent.postMessage(\"poistaRivi:\"+x.getAttribute(\"data-i\")+\"|\"+Date.now(),\"*\");}});";
 function esc(s){ return String(s == null ? "" : s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
 var body = rivit.map(function(r, i){
  var alle = [r.kohde_nimi, [r.tyyppi, r.koko, r.vari, r.materiaali, r.kiinnitys].filter(function(x){return x;}).join(" · ")].filter(function(x){return x;}).join("  —  ");
  return "<tr><td class=\"n\">" + (i + 1) + "</td><td><div class=\"nimi\">" + esc(r.teksti) + (r.huoneisto ? " <span class=\"alle\">(" + esc(r.huoneisto) + ")</span>" : "") + "</div><div class=\"alle\">" + esc(alle) + "</div></td><td class=\"x\"><span class=\"poista\" data-i=\"" + i + "\">&times;</span></td></tr>";
 }).join("");
 if (!rivit.length) { body = "<tr><td class=\"tyhja\" colspan=\"3\">Ei viel\u00e4 kilpi\u00e4 listalla.</td></tr>"; }
 return "<html><head><meta charset=\"utf-8\"><style>" + CSS + "</style></head><body><table>" + body + "</table><script>" + JS + "<\/script></body></html>";
})() }}
